//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF27000.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_FromDate.text = cGetMinusDate2(vCurDate, 7); 	// 일주일전 날짜
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    panel_mkt.style.display = "none";
    $c.stf.setObjectValue(rdo_MKT_ID, "9");
    $c.stf.setObjectValue(cmb_Basis, "2");

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시상세--;
목록검색;
클릭-- > function() {
    /*
    if (vKeyword == '' ) {
    	if (vIsurCd == '' &&  vFssUnqNm == '' && vFormNm == '' 
    		&& (vRsnclssCnt =='' || vRsnclssCnt == '0') ) {
    		alert("법인코드(명), 제출의무자명, 공시제목, 사유분류 중 하나 이상을  입력하셔야 합니다." );
    		txb_isur_cd.focus();
    		return;	
    	}
    } 
    */

    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }

    // 4년 이상의 기간은 검색 할 수 없다
    /*
    var edt_FromDate_year = getObjectValue(edt_FromDate).substr(0,4);
    var edt_FromDate_month = getObjectValue(edt_FromDate).substr(4,2)-1;
    var edt_FromDate_day = getObjectValue(edt_FromDate).substr(6,2);
    var edt_FromDate_Date = new Date(edt_FromDate_year,edt_FromDate_month,edt_FromDate_day);

    var edt_ToDate_year = getObjectValue(edt_ToDate).substr(0,4);
    var edt_ToDate_month = getObjectValue(edt_ToDate).substr(4,2)-1;
    var edt_ToDate_day = getObjectValue(edt_ToDate).substr(6,2);
    var edt_ToDate_Date = new Date(edt_ToDate_year,edt_ToDate_month,edt_ToDate_day);
    var date_result = ( Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date) ) / ( 1000*60*60*24 );

    if ( date_result > 1461) {
    	alert("검색기간은 4년 이상을 초과 할 수 없습니다." );
    	return;	
    }
    */

    fn_Search();
} < !공시상세--;
클릭-- > function() {
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    //btn_Search.disabled = true;
    //btn_Search.src = "../img/btn_select_d.gif";

    var url = "/DisclosureSearch.do?method=listVoterghtExerDiscls"; //의결권행사공시 리스트
    url += "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate); //시작일
    url += "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate); //종료일
    url += "&FSS_UNQ_NO=" + $c.stf.getObjectValue(txb_FssUnqNo); //제출의무자코드
    url += "&FSS_UNQ_NM=" + $c.stf.getObjectValue(txb_FssUnqNm); //제출의무자명
    url += "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
    url += "&LAST_YN=" + scwin.getChkValue(chb_Last); //최종보고서여부
    url += "&BASIS_TP=" + $c.stf.getObjectValue(cmb_Basis); //기간구분
    url += "&DISCLS_OBJ_CORP_ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd); //대상법인
    url += "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd); //서식코드
    url += "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm); //서식명
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.fn_resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    $c.stf.setObjectValue(edt_FromDate, vCurrDate);
    $c.stf.setObjectValue(edt_ToDate, vCurrDate);
    $c.stf.setObjectValue(txb_FssUnqNm, "");
    $c.stf.setObjectValue(txb_FssUnqNo, "");
    $c.stf.setObjectValue(txb_isur_cd, "");
    $c.stf.setObjectValue(txb_com_abbrv, "");
    scwin.setChkValue(chb_Last, false);
    $c.stf.setObjectValue(txb_FormCd, "");
    $c.stf.setObjectValue(txb_FormNm, "");
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(eval(obj), "ISUR_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.dts_DsclList_OnLoadError = function() {
    //alert_error("OnLoadError => "+dts_DsclList);	
    //CloseWin('', grd_Grid); 
    $c.win.alert(dts_DsclList.errorMsg);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
    //if (dts_DsclList.errorMsg) {
    //	alert("OnLoadCompleted => "+dts_DsclList.errorMsg);
    //} else {
    //btn_Search.disabled = false;
    //btn_Search.src = "../img/btn_select.gif";
    //}

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    //btn_Search.disabled = false;
    //btn_Search.src = "../img/btn_select.gif";

    //CloseWin(totalCnt, grd_Grid); 

};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "의결권공시상세검색", "", "8");
};
scwin.btn_Cancel_onclick = function() {
    scwin.fn_resetParam();
};
scwin.image_2_onclick = function() {
    //의결권공시제출인 변경 20160520
    $c.cm.submitSearch_Voting(txb_FssUnqNo, txb_FssUnqNm);
};
scwin.txb_FssUnqNm_onblur = function() {
    if (txb_FssUnqNm.getValue() == "") {
        txb_FssUnqNo.setValue("");
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(txb_FssUnqNo, false);
    scwin.fn_SetCode();

    // 가우스헤더 셋팅
    //dts_Dscl_Cond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLDETAILCOND_IN";
    //dts_Dscl_Cond.reset();

    fn_CheckCond();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
    } else if (colid == "COM_ABBRV") {
        //일괄신고 회사정보 팝업 금지 요청시 주석 풀것
        var v_com_abbrv = dts_DsclList.getCellData(row, "COM_ABBRV");
        if (v_com_abbrv == "일괄신고") {
            //일괄신고는 회사정보팝업 제외
            $c.win.alert('일괄신고입니다.');
        } else {
            $c.stf.fn_PopupCorpInfo();
        }
    }
};
scwin.txb_FormCd_onblur = function() {
    if (txb_FormCd.getValue() == "") {
        txb_FormNm.setValue("");
    }
};
scwin.txb_FormNm_onblur = function() {
    if (txb_FormNm.getValue() == "") {
        txb_FormCd.setValue("");
    }
};
scwin.img_FindForm_onclick = async function() {
    // *** 셋팅할 필드명 정의를 아래처럼 해야함.
    // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
    var url = "/common/ULDSTF91003_10.gfm";
    var winTitle = "공시제목선택 ";
    await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 695, 575, "window");
};
scwin.txb_FssUnqNm_onkeyup = function() {
    var v_txb_FssUnqNo = $c.stf.getObjectValue(txb_FssUnqNo);
    if (v_txb_FssUnqNo != '') {
        $c.stf.setObjectValue(txb_FssUnqNo, '');
    }
    if (window.event.keyCode == "13") {
        fn_Search();
    }
};
